import{_ as e,o,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"写作模板","description":"","frontmatter":{},"headers":[],"relativePath":"templates/index.md","filePath":"templates/index.md","lastUpdated":1786327499000}'),l={name:"templates/index.md"};function r(i,t,s,c,n,p){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="写作模板" tabindex="-1">写作模板 <a class="header-anchor" href="#写作模板" aria-label="Permalink to &quot;写作模板&quot;">​</a></h1><p>这个知识库的价值不在第一版写了多少，而在于<strong>每做完一件事都往回填</strong>。</p><p>填的时候不要从空白页开始——空白页会让人拖延，也会让每篇的结构都不一样，久了就没法横向对比。用模板。</p><h2 id="三个模板" tabindex="-1">三个模板 <a class="header-anchor" href="#三个模板" aria-label="Permalink to &quot;三个模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板</th><th>什么时候用</th><th>存到哪</th></tr></thead><tbody><tr><td><a href="/templates/prompt-card">Prompt 卡片模板</a></td><td>调通了一条 Prompt</td><td><code>docs/prompts/</code></td></tr><tr><td><a href="/templates/case-study">案例拆解模板</a></td><td>做完一个项目</td><td><code>docs/cases/</code></td></tr><tr><td><a href="/templates/tool-review">工具评测模板</a></td><td>试完一个新工具</td><td><code>docs/tools/</code></td></tr></tbody></table><h2 id="加一篇新文章的完整步骤" tabindex="-1">加一篇新文章的完整步骤 <a class="header-anchor" href="#加一篇新文章的完整步骤" aria-label="Permalink to &quot;加一篇新文章的完整步骤&quot;">​</a></h2><ol><li>复制对应模板的骨架，在目标目录新建 <code>.md</code> 文件（文件名用英文小写连字符，如 <code>perfume-key-visual.md</code>）</li><li>打开 <code>docs/.vitepress/config.mts</code>，在 <code>sidebar</code> 对应板块的 <code>items</code> 里加一行</li><li><code>npm run docs:dev</code> 本地看一眼</li><li><code>git commit</code> + <code>git push</code>，1–2 分钟后线上生效</li></ol><div class="warning custom-block"><p class="custom-block-title">第 2 步不能省</p><p>不在 <code>config.mts</code> 里加链接，文章不会出现在侧边栏——虽然搜索还能搜到，但基本等于没写。</p></div><h2 id="什么值得写" tabindex="-1">什么值得写 <a class="header-anchor" href="#什么值得写" aria-label="Permalink to &quot;什么值得写&quot;">​</a></h2><p>一个筛选标准：<strong>下次遇到同类需求，这条记录能帮你省多少时间？</strong></p><p>值得写：</p><ul><li>试了五版才调对的 Prompt，<strong>以及前四版为什么不行</strong></li><li>某个效果做不出来，最后靠换链路绕过去的</li><li>客户反复否掉的方向（避坑同样是资产）</li><li>某个工具在你的具体场景里的实际出片率</li></ul><p>不值得写：</p><ul><li>官网文档上抄来的参数（会过时，随时能查）</li><li>只用一次的一次性内容</li><li>没有结论的流水账</li></ul><h2 id="一条写作原则" tabindex="-1">一条写作原则 <a class="header-anchor" href="#一条写作原则" aria-label="Permalink to &quot;一条写作原则&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">失败的记录比成功的更值钱</p><p>&quot;这个方法有效&quot;只在当时的条件下成立，条件一变就未必。 &quot;这个方法无效，因为 X&quot; 标记的是<strong>边界</strong>，边界比路径稳定得多。</p><p>所以三个模板里都留了「失败的尝试」「翻车点」「如果重做一次」这类段落。<strong>不要跳过它们。</strong></p></div>',16)])])}const u=e(l,[["render",r]]);export{m as __pageData,u as default};
